exploreUrl:
@js:
var url = source.key
var result = [];
var push = (title, url, type) => result.push({
    title: title, url: url,
    style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type } });

try {
push("🏷️全部分类🏷️",null, 1)

lis=org.jsoup.Jsoup.parse(java.ajax(source.key)).select(".nav a");
for (var i = 0; i < lis.length-1; i++) {
    text = lis[i].select('a').text();
    href = url +String(lis[i].select('a').attr('href')).replace(/\d+\.html$/,"{{page}}.html");
    push(text, href, 0.33);
}
  java.toast("🎉 列表刷新完成，数据已更新❗");
  JSON.stringify(result); 

} catch (error) {
  java.toast("❌ 列表刷新失败，未获取到数据❗");
}

