ruleBookInfo.init:
@js:
(function(){
    let doc = org.jsoup.Jsoup.parse(result)
    let og = (selector) => doc.select('[property="og:' + selector + '"]').attr('content')||""
    return {
    n: og('novel:book_name'),
    a: og('novel:author'),
    k: [og('novel:category'),og('novel:status'),
(og('novel:update_time'))].filter(Boolean).join('•'),   
    w:('{{@@##字数：([^<]+)<##$1###}}'),
    l: og('novel:latest_chapter_name'),
    i: og('description'),
    c: og('image'),
    t: og('novel:read_url')
    }
})()

